/**
 * Every request carries the organisation currently being viewed.
 *
 * The tenant_isolation policies read this header and narrow to it, which is
 * how a user who belongs to two companies sees one at a time without every
 * query in the app having to remember an .eq('organization_id', ...) — and
 * without the ones that forget silently showing another company's data.
 *
 * It is injected here rather than passed to createClient because the value
 * changes when the user switches, and a header fixed at construction would
 * keep pointing at whichever organisation loaded first.
 */
const fetchWithActiveOrg: typeof fetch = (input, init) => {
  const orgId = getActiveOrgHeader();
  if (!orgId) return fetch(input, init);
  const headers = new Headers(init?.headers);
  headers.set(ACTIVE_ORG_HEADER, orgId);
  return fetch(input, { ...init, headers });
};

export const supabase = createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
  auth: {
    storage: localStorage,
    persistSession: true,
    autoRefreshToken: true,
  },
  global: { fetch: fetchWithActiveOrg },
});
